/* === RESET === */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.7;
  min-height: 100vh;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

ul {
  list-style: none;
}

/* === DESIGN TOKENS === */
:root {
  --bg: #F5F2ED;
  --text: #1A1A1A;
  --text-light: #6B6560;
  --text-muted: #9E9892;
  --border: #E5E0D9;
  --accent-terracotta: #C17D5E;
  --accent-sage: #8B9D83;
  --accent-sand: #D4C5B9;
  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --max-width: 1200px;
  --max-width-narrow: 640px;
}

/* === TYPOGRAPHY === */
h1, h2, h3, h4 {
  font-family: var(--font-serif);
  font-weight: 700;
  line-height: 1.15;
}

p {
  margin-bottom: 1.5rem;
  color: var(--text-light);
}

p:last-child {
  margin-bottom: 0;
}

/* === HEADER === */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 1.5rem 3rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: transparent;
  transition: background 0.3s ease;
}

.site-header.scrolled {
  background: rgba(245, 242, 237, 0.92);
  backdrop-filter: blur(12px);
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text);
  letter-spacing: -0.02em;
}

.nav-list {
  display: flex;
  gap: 2.5rem;
}

.nav-list a {
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-light);
  transition: color 0.2s ease;
  position: relative;
}

.nav-list a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--text);
  transition: width 0.3s ease;
}

.nav-list a:hover {
  color: var(--text);
}

.nav-list a:hover::after,
.nav-list a.active::after {
  width: 100%;
}

.nav-list a.active {
  color: var(--text);
}

/* === HAMBURGER === */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 44px;
  height: 44px;
  background: none;
  border: none;
  cursor: pointer;
  z-index: 200;
  position: relative;
  padding: 0;
}

.hamburger-line {
  display: block;
  width: 24px;
  height: 1.5px;
  background: var(--text);
  transition: transform 0.3s ease, opacity 0.3s ease;
  position: absolute;
}

.hamburger-line:nth-child(1) {
  transform: translateY(-7px);
}

.hamburger-line:nth-child(3) {
  transform: translateY(7px);
}

.menu-open .hamburger-line:nth-child(1) {
  transform: translateY(0) rotate(45deg);
}

.menu-open .hamburger-line:nth-child(2) {
  opacity: 0;
}

.menu-open .hamburger-line:nth-child(3) {
  transform: translateY(0) rotate(-45deg);
}

/* === MOBILE OVERLAY === */
.mobile-overlay {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 150;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.menu-open .mobile-overlay {
  opacity: 1;
  pointer-events: auto;
}

.mobile-nav-list {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
}

.mobile-nav-list a {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--text);
  transition: opacity 0.2s ease;
}

.mobile-nav-list a:hover {
  opacity: 0.6;
}

/* === MAIN === */
main {
  padding-top: 0;
}

/* === HERO === */
.hero {
  padding: 10rem 3rem 6rem;
  min-height: 70vh;
  display: flex;
  align-items: flex-end;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
  max-width: 12ch;
  color: var(--text);
}

/* === MEDIA SHOWCASE === */
.media-showcase {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  width: 100%;
  padding: 0 3rem;
}

.media-block {
  aspect-ratio: 4 / 3;
  width: 100%;
}

.media-block:nth-child(1) {
  background-color: var(--accent-terracotta);
}

.media-block:nth-child(2) {
  background-color: var(--accent-sage);
}

.media-block:nth-child(3) {
  background-color: var(--accent-sand);
}

/* === CLIENT MARQUEE === */
.marquee-section {
  padding: 8rem 0;
  overflow: hidden;
}

.marquee-row {
  overflow: hidden;
  padding: 1.5rem 0;
}

.marquee-row + .marquee-row {
  border-top: 1px solid var(--border);
}

.marquee-row:first-child {
  border-top: 1px solid var(--border);
}

.marquee-row:last-child {
  border-bottom: 1px solid var(--border);
}

.marquee-track {
  display: flex;
  width: max-content;
  will-change: transform;
}

.marquee-track.forward {
  animation: marquee-forward 40s linear infinite;
}

.marquee-track.reverse {
  animation: marquee-reverse 40s linear infinite;
}

.marquee-item {
  font-family: var(--font-serif);
  font-size: clamp(1.75rem, 3.5vw, 3rem);
  font-weight: 700;
  color: var(--text);
  white-space: nowrap;
  padding: 0 1.5rem;
  flex-shrink: 0;
}

.marquee-sep {
  color: var(--text-muted);
  padding: 0 0.5rem;
}

@keyframes marquee-forward {
  0% {
    transform: translate3d(0, 0, 0);
  }
  100% {
    transform: translate3d(-50%, 0, 0);
  }
}

@keyframes marquee-reverse {
  0% {
    transform: translate3d(-50%, 0, 0);
  }
  100% {
    transform: translate3d(0, 0, 0);
  }
}

/* === ABOUT SECTION === */
.about-section {
  padding: 8rem 3rem 10rem;
}

.section-label {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 2.5rem;
}

.about-content {
  max-width: var(--max-width-narrow);
}

.about-content p {
  font-size: 1.125rem;
  line-height: 1.8;
}

/* === FOUNDER LETTER === */
.founder-letter {
  padding: 8rem 3rem 10rem;
  max-width: var(--max-width-narrow);
  margin: 0 auto;
}

.founder-letter h1 {
  font-size: clamp(2rem, 3.5vw, 3rem);
  margin-bottom: 3rem;
  color: var(--text);
}

.founder-letter .letter-body {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  line-height: 1.85;
  color: var(--text);
}

.founder-letter .letter-body p {
  font-family: var(--font-serif);
  color: var(--text);
  margin-bottom: 2rem;
  text-indent: 0;
}

.founder-letter .signature {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  margin-top: 4rem;
  color: var(--text);
}

/* === PHILOSOPHY === */
.philosophy-section {
  padding: 10rem 3rem 6rem;
}

.philosophy-section h1 {
  font-size: clamp(2rem, 4vw, 3.5rem);
  margin-bottom: 2rem;
  color: var(--text);
}

.philosophy-content {
  max-width: var(--max-width-narrow);
}

.philosophy-content p {
  font-size: 1.125rem;
  line-height: 1.8;
}

/* === DIVIDER === */
.section-divider {
  width: 100%;
  height: 1px;
  background: var(--border);
  margin: 6rem 0;
}

/* === SERVICE DETAILS === */
.services-section {
  padding: 0 3rem 10rem;
}

.services-section .section-label {
  margin-bottom: 3rem;
}

.services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 4rem;
  max-width: var(--max-width);
}

.service-card h2 {
  font-size: 1.75rem;
  margin-bottom: 1.25rem;
  color: var(--text);
}

.service-card p {
  font-size: 1rem;
  line-height: 1.8;
}

/* === CLIENTS PAGE === */
.clients-section {
  padding: 10rem 3rem 10rem;
}

.clients-section h1 {
  font-size: clamp(2rem, 4vw, 3.5rem);
  margin-bottom: 4rem;
  color: var(--text);
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem 2rem;
  max-width: var(--max-width);
}

.client-card h3 {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text);
  margin-bottom: 0.5rem;
}

.client-card p {
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--text-light);
}

/* === CONTACT PAGE === */
.contact-section {
  padding: 6rem 3rem 10rem;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.contact-heading {
  font-family: var(--font-serif);
  font-size: clamp(4rem, 12vw, 10rem);
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: -0.03em;
  color: var(--text);
  margin-bottom: 3rem;
}

.contact-links {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.contact-links a {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 700;
  color: var(--text-light);
  transition: color 0.3s ease;
  display: inline-block;
  width: fit-content;
}

.contact-links a:hover {
  color: var(--text);
}

/* === FOOTER === */
.site-footer {
  padding: 3rem;
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* === RESPONSIVE === */
@media (max-width: 768px) {
  .site-header {
    padding: 1.25rem 1.5rem;
  }

  .nav-list {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .hero {
    padding: 8rem 1.5rem 4rem;
    min-height: 50vh;
  }

  .media-showcase {
    grid-template-columns: 1fr;
    padding: 0 1.5rem;
    gap: 0.5rem;
  }

  .media-block {
    aspect-ratio: 16 / 9;
  }

  .marquee-section {
    padding: 4rem 0;
  }

  .marquee-row {
    padding: 1rem 0;
  }

  .about-section {
    padding: 4rem 1.5rem 6rem;
  }

  .founder-letter {
    padding: 6rem 1.5rem 6rem;
  }

  .founder-letter .letter-body {
    font-size: 1.125rem;
  }

  .philosophy-section {
    padding: 6rem 1.5rem 4rem;
  }

  .services-section {
    padding: 0 1.5rem 6rem;
  }

  .services-grid {
    grid-template-columns: 1fr;
    gap: 3rem;
  }

  .clients-section {
    padding: 6rem 1.5rem 6rem;
  }

  .clients-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .contact-section {
    padding: 4rem 1.5rem 6rem;
  }

  .site-footer {
    padding: 2rem 1.5rem;
    flex-direction: column;
    gap: 0.5rem;
    text-align: center;
  }
}

@media (max-width: 1024px) and (min-width: 769px) {
  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .services-grid {
    gap: 2rem;
  }
}

