/* === RESET === */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.7;
  min-height: 100vh;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

ul {
  list-style: none;
}

/* === DESIGN TOKENS === */
:root {
  --bg: #F5F2ED;
  --text: #1A1A1A;
  --text-light: #6B6560;
  --text-muted: #9E9892;
  --border: #E5E0D9;
  --accent-terracotta: #C17D5E;
  --accent-sage: #8B9D83;
  --accent-sand: #D4C5B9;
  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --max-width: 1200px;
  --max-width-narrow: 640px;
}

/* === TYPOGRAPHY === */
h1, h2, h3, h4 {
  font-family: var(--font-serif);
  font-weight: 700;
  line-height: 1.15;
}

p {
  margin-bottom: 1.5rem;
  color: var(--text-light);
}

p:last-child {
  margin-bottom: 0;
}

/* === HEADER === */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 1.5rem 3rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: transparent;
  transition: background 0.3s ease;
}

.site-header.scrolled {
  background: rgba(245, 242, 237, 0.92);
  backdrop-filter: blur(12px);
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text);
  letter-spacing: -0.02em;
}

.nav-list {
  display: flex;
  gap: 2.5rem;
}

.nav-list a {
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-light);
  transition: color 0.2s ease;
  position: relative;
}

.nav-list a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--text);
  transition: width 0.3s ease;
}

.nav-list a:hover {
  color: var(--text);
}

.nav-list a:hover::after,
.nav-list a.active::after {
  width: 100%;
}

.nav-list a.active {
  color: var(--text);
}

/* === HAMBURGER === */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 44px;
  height: 44px;
  background: none;
  border: none;
  cursor: pointer;
  z-index: 200;
  position: relative;
  padding: 0;
}

.hamburger-line {
  display: block;
  width: 24px;
  height: 1.5px;
  background: var(--text);
  transition: transform 0.3s ease, opacity 0.3s ease;
  position: absolute;
}

.hamburger-line:nth-child(1) {
  transform: translateY(-7px);
}

.hamburger-line:nth-child(3) {
  transform: translateY(7px);
}

.menu-open .hamburger-line:nth-child(1) {
  transform: translateY(0) rotate(45deg);
}

.menu-open .hamburger-line:nth-child(2) {
  opacity: 0;
}

.menu-open .hamburger-line:nth-child(3) {
  transform: translateY(0) rotate(-45deg);
}

/* === MOBILE OVERLAY === */
.mobile-overlay {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 150;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.menu-open .mobile-overlay {
  opacity: 1;
  pointer-events: auto;
}

.mobile-nav-list {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
}

.mobile-nav-list a {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--text);
  transition: opacity 0.2s ease;
}

.mobile-nav-list a:hover {
  opacity: 0.6;
}

/* === MAIN === */
main {
  padding-top: 0;
}

/* === HERO === */
.hero {
  padding: 10rem 3rem 6rem;
  min-height: 70vh;
  display: flex;
  align-items: flex-end;
}

.hero-title {
